//! 🧪️ Appending retains the same page on refusal and transfers it before an enclosing receipt can refuse.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::retained_clone::RetainedCloneClose;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(941),Generation(41),RetainedCloneGrant{maximum_items:1<<20,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<26,maximum_depth:4096},semio_framework_job::default_now_us,u64::MAX,1<<20)}
fn retire<T:semio_framework_value::retirement::RetireOwned>(caller:&mut OriginalJobFixtureCaller,value:T){let mut value=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..10000{if value.is_none()&&close.is_empty(){return}caller.turn(grant(),|cx|{let d=close.next_owner_demands::<T>(value.is_some(),&None,32768)?;semio_framework_job::close_original_retained_step(cx,d,|g|if close.is_empty(){let t=close.begin_granted(&mut value,g);semio_framework_value::RetainedWorkOutcome{result:t.result.map(|s|s.unwrap()),work:t.work}}else{close.step_granted(g)})?;Ok(())}).unwrap();}panic!("finite original append retirement")}
#[test]
fn original_producer_custody_preserves_page_pointer_and_is_neutral_on_each_denied_axis(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let expected:Vec<u8>=serde_json::from_value(law["page"].clone()).unwrap();let mut caller=caller();let mut chunks=None;caller.turn(grant(),|cx|ArtifactOutputChunks::original_birth_admit(law["maximumBytes"].as_u64().unwrap()as usize,&mut chunks,cx)).unwrap();let chunks=chunks.unwrap();let mut page=Some(expected.clone());let pointer=page.as_ref().unwrap().as_ptr();let d=ArtifactOutputChunks::original_producer_custody_demands();
 for axis in law["deniedAxes"].as_array().unwrap(){let mut g=grant();match axis.as_str().unwrap(){"items"=>g.maximum_items=0,"copy"=>g.maximum_copy_bytes=d.copy_bytes-1,"depth"=>g.maximum_depth=0,_=>unreachable!()}caller.turn(g,|cx|{assert!(!chunks.push_original(&mut page,None,cx)?);Ok(())}).unwrap();assert_eq!(page.as_ref().unwrap().as_ptr(),pointer);assert_eq!(chunks.bytes(),0);}
 caller.turn(grant(),|cx|{assert!(chunks.push_original(&mut page,None,cx)?);Ok(())}).unwrap();assert!(page.is_none());caller.turn(grant(),|cx|{assert!(chunks.push_original(&mut page,None,cx).is_err());Ok(())}).unwrap();assert_eq!(chunks.bytes(),expected.len());caller.turn(grant(),|cx|chunks.seal_original(cx)).unwrap();let mut output=None;let mut terminal=false;caller.turn(grant(),|cx|chunks.take_chunk_original(&mut output,&mut terminal,cx)).unwrap();assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.as_ref().unwrap(),&expected);assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),law["page"]);retire(&mut caller,output);retire(&mut caller,chunks);caller.retire(grant());
}
#[test]
fn original_producer_custody_refusal_never_takes_or_reallocates_the_source(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for refusal in law["refusals"].as_array().unwrap(){let mut caller=caller();let mut chunks=None;caller.turn(grant(),|cx|ArtifactOutputChunks::original_birth_admit(if refusal=="total-capacity"{1}else{4096},&mut chunks,cx)).unwrap();let chunks=chunks.unwrap();if refusal=="sealed"{caller.turn(grant(),|cx|chunks.seal_original(cx)).unwrap();}let mut page=Some(match refusal.as_str().unwrap(){"empty"=>Vec::new(),"oversized"=>vec![1;4097],_=>vec![1,2]});let pointer=page.as_ref().unwrap().as_ptr();caller.turn(grant(),|cx|{assert!(chunks.push_original(&mut page,None,cx).is_err());Ok(())}).unwrap();assert_eq!(page.as_ref().unwrap().as_ptr(),pointer);assert_eq!(chunks.bytes(),0);retire(&mut caller,page);retire(&mut caller,chunks);caller.retire(grant());}}
#[test]
fn original_producer_custody_queue_keeps_the_actual_page_after_enclosing_receipt_refusal(){let mut caller=caller();let mut chunks=None;caller.turn(grant(),|cx|ArtifactOutputChunks::original_birth_admit(4096,&mut chunks,cx)).unwrap();let chunks=chunks.unwrap();let mut page=Some(vec![7,8,9]);let pointer=page.as_ref().unwrap().as_ptr();let g=RetainedCloneGrant{maximum_copy_bytes:ArtifactOutputChunks::original_producer_custody_demands().copy_bytes,..grant()};let error=caller.turn(g,|cx|{chunks.push_original(&mut page,None,cx)?;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()})?;Ok(())}).unwrap_err();assert!(page.is_none());assert_eq!(chunks.bytes(),3);caller.turn(grant(),|cx|chunks.seal_original(cx)).unwrap();let mut output=None;let mut terminal=false;caller.turn(grant(),|cx|chunks.take_chunk_original(&mut output,&mut terminal,cx)).unwrap();assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);retire(&mut caller,error);retire(&mut caller,output);retire(&mut caller,chunks);caller.retire(grant());}
